insert into usage_log (user_hash, chat_hash) values ($1, $2)
returning $3::text as "chatInput", $4::text as "sessionId";

parameters.jsCode:
// Question router, step 1: one small classification call BEFORE the agent decides anything.
// Classifies: does this question need the web (none / verified / verified + wider web)? Is it a review request? And how
// to read it: typos and clipped words ("Fall" for "Outfall"), judged against library terms that look like words in
// the message (node "Library vocabulary"; if that lookup failed, the router just works without candidates).
const lk = $json.lookup ?? null;
// fallback by position, not item pairing: a failed query's error item has no pairing back (tested 2026-10-22)
const pick = name => { const all = $(name).all(); return (all[$itemIndex] ?? all[0])?.json ?? {}; };
const base = $json.chatInput !== undefined ? $json
  : ($('Log usage (no text)').isExecuted ? pick('Log usage (no text)') : pick('When chat message received'));
const { lookup, error, ...keep } = base;
const vocab = (lk?.vocab ?? []).slice(0, 12).map(v => `${v.said} -> ${v.library_term} (${v.files} files)`);
// the message goes to the router exactly as before (a "Message:" prefix shifted web routing on demo D4); candidates,
// when there are any, follow as a separate system note
const candNote = vocab.length
  ? [{ role: 'system', content: 'Library terms that look like words in the message (word as typed -> library term, files containing it), for the reading field only: ' + vocab.join('; ') }] : [];
const ROUTER_PROMPT = "You route questions for an engineering knowledge assistant whose primary source is the organization's internal documents (manuals, SOPs, design guides, templates, spreadsheets, plan sets, training). Return JSON {web, review, reading}.\nweb:\n- \"none\": how-to steps; what a document, sheet, figure or template says; spreadsheet values or calculations; internal procedures; people or projects — anything the internal documents should fully answer.\n- \"verified\": asks about CURRENT / latest / recent / updated regulations, requirements, permits, criteria or official guidance, or names an external regulation or agency standard.\n- \"verified_and_open\": asks about technologies, products, materials, vendors, newer or emerging approaches, industry practice, or explicitly asks for web / outside / wider / other sources.\nreview: true when the user asks to review, update, check, modernize or compare a template, standard, SOP, checklist, scope of work or guideline (then web must be at least \"verified\").\nreading: words or short phrases the user most likely mistyped, clipped or misspelled, with what they meant. People type fast: typos, dropped letters, clipped words, British spellings, swapped acronym letters, shorthand (reqs = requirements, geotech = geotechnical). The system lists library terms that look like words in the message (candidates); judge them with the rest of the sentence. Example: \"Fall stabilisation design scope on creeks that feed the river\" -> \"Fall\" meant \"outfall\" (outfalls drain to streams; \"outfall\" is common in the library). Leave a word alone when it makes sense as typed: \"fall protection\", \"fall seeding\", \"in the fall\", \"rainfall\". Never change identifiers (sheet, drawing, project or file numbers such as C-08, PR1234). Do not list a correctly typed acronym or abbreviation just to expand it (ROE, SOP, BMP, MS4): list it only when its letters are wrong (NPEDS -> NPDES). change: \"meaning\" when the reading changes what is asked (Fall -> outfall); \"spelling\" for typos and spelling variants that don't (complant -> complaint, stabilisation -> stabilization). Empty list when the message reads fine.";
return { json: { ...keep, libraryFiles: lk?.files ?? [], routerBody: {
  model: 'gpt-5.4-mini', reasoning_effort: 'low', max_completion_tokens: 1000,
  response_format: { type: 'json_schema', json_schema: { name: 'route', strict: true, schema: {
    type: 'object', additionalProperties: false, required: ['web', 'review', 'reading'],
    properties: { web: { type: 'string', enum: ['none', 'verified', 'verified_and_open'] }, review: { type: 'boolean' },
      reading: { type: 'array', items: { type: 'object', additionalProperties: false, required: ['said', 'meant', 'change'],
        properties: { said: { type: 'string' }, meant: { type: 'string' }, change: { type: 'string', enum: ['meaning', 'spelling'] } } } } } } } },
  messages: [ { role: 'system', content: ROUTER_PROMPT }, { role: 'user', content: String(keep.chatInput ?? '') }, ...candNote ],
} } };

// Question router, step 3: turn the classification into an instruction appended to the agent's system message
// for THIS question only (it is not stored in chat memory). If routing failed, no note — the agent decides itself.
const src = $('Build routing request').item.json;
let route = {};                                   // unparsable / failed routing → no note at all
try { route = JSON.parse($json.choices?.[0]?.message?.content ?? '{}') ?? {}; } catch (e) {}
let note = '';
if (route.web === 'none' && !route.review) note += '\n\nROUTING FOR THIS QUESTION (from the system, not the user): answer from the documents only — do not call search_web or search_open_web.';
if (route.review) note += '\n\nROUTING FOR THIS QUESTION (from the system, not the user): this is a review-mode request — follow rule 9, including its web steps.';
if (route.web === 'verified' || route.web === 'verified_and_open') {
  note += '\n\nROUTING FOR THIS QUESTION (from the system, not the user): after searching the documents you MUST call search_web' +
    (route.web === 'verified_and_open' ? ', then search_open_web,' : '') + ' and answer with the labelled sections from rule 8.';
}
// How to read the message (router + library vocabulary). Meaning changes are said out loud in the answer; spelling
// fixes are silent. Identifiers (anything with a digit) are never reinterpreted.
// Guards (Scrutiny 2026-10-22): the word must really be in the message; short, single-line strings only; and a change
// that is not plausibly a spelling fix or an abbreviation is always said out loud, whatever the router labelled it.
const clean = (x, n) => String(x ?? '').replace(/[\r\n*_`"<>]/g, ' ').replace(/\s+/g, ' ').trim().slice(0, n);
const asked = String(src.chatInput ?? '').toLowerCase();
const lev = (a, b) => { const d = Array.from({ length: a.length + 1 }, (_, i) => [i]);
  for (let j = 1; j <= b.length; j++) d[0][j] = j;
  for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++)
    d[i][j] = Math.min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1));
  return d[a.length][b.length]; };
const subseq = (a, b) => { let i = 0; for (const ch of b) if (ch === a[i]) i++; return i === a.length; };
const spellingLike = (a, b) => lev(a, b) <= 2 || b.startsWith(a) || (a[0] === b[0] && subseq(a, b));   // stabilisation, geotech, reqs
const readings = (Array.isArray(route.reading) ? route.reading : [])
  .map(r => ({ said: clean(r?.said, 40), meant: clean(r?.meant, 40), change: r?.change }))
  .filter(r => r.said && r.meant && r.said.toLowerCase() !== r.meant.toLowerCase() && !/\d/.test(r.said)
               && new RegExp('(^|[^a-z0-9])' + r.said.toLowerCase().replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '([^a-z0-9]|$)').test(asked))
  // an all-caps acronym "read" as its long form is an expansion, not a fix (ROE -> right-of-entry, demo 2026-10-22)
  // (only true expansions: the long form's initials spell the acronym, so "FALL" -> outfall typed in capitals survives)
  .filter(r => !(/^[A-Z]{2,}$/.test(r.said)
                 && r.meant.split(/[\s\-\/]+/).filter(Boolean).map(x => x[0]).join('').toLowerCase() === r.said.toLowerCase()))
  .map(r => ({ ...r, change: r.change === 'meaning' || !spellingLike(r.said.toLowerCase(), r.meant.toLowerCase()) ? 'meaning' : 'spelling' }))
  .slice(0, 4);
const meaning = readings.filter(r => r.change === 'meaning');
const spelling = readings.filter(r => r.change !== 'meaning');
if (meaning.length) note += '\n\nHOW TO READ THIS MESSAGE (from the system, not the user): ' + meaning.map(r => `"${r.said}" most likely means "${r.meant}"`).join('; ')
  + '. Search for and answer the intended meaning, and begin the answer with one short line such as: _I read "' + meaning[0].said + '" as **'
  + meaning[0].meant + '**; tell me if you meant something else._';
if (spelling.length) note += '\n\nSPELLING (from the system): search with the corrected words (' + spelling.map(r => `${r.said} -> ${r.meant}`).join(', ')
  + '). Do not mention these corrections.';
const files = (src.libraryFiles || []).slice(0, 10).map(f => clean(f, 150)).filter(Boolean);
if (files.length) note += '\n\nFILES WHOSE NAMES MATCH WORDS IN THE MESSAGE (from the system; only for checking a document the user names, not a reading list): '
  + files.join('; ');
const { routerBody, libraryFiles, ...rest } = src;
return { json: { ...rest, route, routingNote: note } };

// Append the web sections FROM CODE, not from the model: every finding and link exactly as the web tools returned
// them, already sorted by trust level. The model only writes the documents part, so a source can never be relabelled,
// paraphrased or dropped. (The agent returns its tool calls as intermediateSteps.)
const out = String($json.output ?? '');
const steps = Array.isArray($json.intermediateSteps) ? $json.intermediateSteps : [];
const webSteps = steps.filter(s => ['search_web', 'search_open_web'].includes(s.action?.tool));
if (!webSteps.length) return [{ json: { output: out } }];

const verified = [], wider = [], failures = []; let retrieved = '', openUsed = false;
const add = (list, text) => { for (const b of String(text ?? '').split(/\n\s*\n/).map(x => x.trim()))
  if (b && !b.startsWith('(') && !list.includes(b)) list.push(b); };
for (const s of webSteps) {
  if (s.action.tool === 'search_open_web') openUsed = true;
  let obs = s.observation; try { obs = JSON.parse(obs); } catch (e) {}
  for (const it of (Array.isArray(obs) ? obs : [obs])) {
    const j = it?.json ?? it ?? {};
    add(verified, j.verified_findings); add(wider, j.wider_findings);
    if (String(j.note ?? '').startsWith('Web search failed')) failures.push(j.note);
    retrieved = j.retrieved || retrieved;
  }
}
// drop any web sections the model wrote anyway (from such a heading to the next non-web heading or the end)
// (headings as #-#### or **bold**, anywhere including the very start)
const WEB_HEAD = /(?:^|\n)[ \t]*(?:#{1,4}[ \t]*|\*\*)[ \t]*From (?:verified public sources|the wider web)[\s\S]*?(?=\n[ \t]*(?:#{1,4}[ \t]|\*\*)(?![ \t]*From (?:verified public sources|the wider web))|$)/g;
const body = out.replace(WEB_HEAD, '').trim();
const parts = [body,
  '### From verified public sources (verify before relying)\n' + (verified.length ? verified.join('\n')
    : failures.length ? `_${failures[0]}_` : '_No verified public source covered this._')];
if (openUsed) parts.push('### From the wider web — not on the verified list (use with caution)\n' +
  (wider.length ? wider.join('\n') : '_Nothing credible found beyond the verified list._'));
parts.push(`_Web sources retrieved ${retrieved || new Date().toISOString().slice(0, 10)}._`);
return [{ json: { output: parts.join('\n\n') } }];

// Put each screenshot under the step it illustrates (2026-10-24). The model tends to collect screenshots under the LAST
// step (measured: 61% under the right step). The source passage says where each belongs: the text just BEFORE the
// image in the original document. That text is matched to the answer's steps (shared words); the image moves under
// the best-matching step, next to its best-matching line. Low confidence or no source: the image stays where it is.
// Any error, or a different image count afterwards: the answer is returned unchanged.
// Also a safety net (2026-10-24): a source user guide contains a real login in plain text, so anything shaped like
// "password: …" (or "pwd = …") is hidden in every answer. The real fix is in the source document.
// key (password/passcode/pwd/pw), optional "(case-sensitive)", a separator (: = - is | ：), then a value that LOOKS like a
// credential: 6+ characters, no spaces, with a digit or a symbol. Prose ("is required.", "is case-sensitive.") stays.
const SECRET = /\b(pass ?words?|passcodes?|pwd)\b(\s*\([^)\n]{0,30}\))?(\*{0,2}\s*(?:[:：=–-]|\bis\b:?|\|)\s*\*{0,2}\s*)([^\s*|<>()]+)/gi;
const SECRET_PW = /\b(pw)\b()(\*{0,2}\s*[:：=]\s*\*{0,2}\s*)([^\s*|<>()]+)/gi;   // "PW" only with : or = ("PW-SOP-012" is a Public Works id)
const looksSecret = (v) => { const x = v.replace(/[.,;:!?)\]]+$/, '');
  return x.length >= 6 && /[0-9@#$%^&*!?~+=]/.test(x) && !/^[\d+.,%-]+$/.test(x) && x !== '[removed]'; };
const hide = (m, k, par, sep, v) => looksSecret(v) ? `${k}${par ?? ''}${sep}[removed]` : m;
const redact = (t) => t.replace(SECRET, hide).replace(SECRET_PW, hide);
const original = redact(String($json.output ?? ''));
const tools = Array.isArray($json.intermediateSteps) ? $json.intermediateSteps : [];
const pass = (o) => [{ json: { ...$json, output: o } }];
try {
  const IMG = /!\[[^\]]*\]\((https?:\/\/[^)\s]+)\)/g;
  const IMG1 = /!\[[^\]]*\]\((https?:\/\/[^)\s]+)\)/;
  const STEP = /^\s{0,3}\d+[.)]\s/;                                      // numbered list items (not numbered headings)
  const STOP = new Set('the a an and or of to in on for with by is are be this that from at as it you your click select enter then if into will can'.split(' '));
  const words = (t) => new Set(String(t).replace(IMG, ' ').replace(/\*?Image, page \d+:[^\n]*/gi, ' ').toLowerCase()
    .match(/[a-z0-9]+/g)?.filter(w => w.length > 2 && !STOP.has(w)) ?? []);
  const overlap = (a, b) => { let n = 0; for (const w of a) if (b.has(w)) n++; return n / (Math.sqrt(b.size) + 1); };
  // the passages' own text: parse the tool results and collect their strings (raw text as a fallback)
  const texts = [];
  const collect = (v) => { if (typeof v === 'string') texts.push(v); else if (v && typeof v === 'object') for (const x of Object.values(v)) collect(x); };
  for (const s of tools.filter(s => ['search_documents', 'get_full_document'].includes(s.action?.tool))) {
    let o = s.observation;
    if (typeof o === 'string') { try { o = JSON.parse(o); } catch (e) {} }
    collect(o);
  }
  const contextOf = (url) => {
    for (const o of texts) {
      const i = o.indexOf(url);
      if (i < 0) continue;
      // the document's own text before the image: generated captions (italic lines, "Image, page N: …") removed —
      // a neighbouring screenshot's caption pulled images to the wrong step (manual check, 2026-10-24)
      const before = o.slice(0, o.lastIndexOf('![', i)).replace(/\*?Image, page \d+:[^\n]*/gi, ' ')
        .split('\n').filter(l => !/^\s*\*[^*\n].*\*\s*$/.test(l)).join('\n');
      // since the END of the previous image (full pattern: alt texts can contain ")"): exactly what this one illustrates
      const ends = [...before.matchAll(IMG)].map(m => m.index + m[0].length);
      const own = (ends.length ? before.slice(ends[ends.length - 1]) : before).replace(IMG, ' ');
      // even a short sentence ("3. Go to Groups.") is the right signal; wider text only if it has no real words
      const near = words(own).size ? own.slice(-220) : before.replace(IMG, ' ').slice(-220);
      return { wide: words(before.replace(IMG, ' ').slice(-500)), near: words(near), last: words(near.slice(-120)) };
    }
    return null;
  };
  const lines = original.split('\n');
  const isImgLine = (l) => l.replace(IMG, '').trim() === '' && IMG1.test(l);
  // protected lines are never steps, targets or moved: code fences (and everything inside) and table rows
  const prot = new Array(lines.length).fill(false);
  for (let i = 0, fence = false; i < lines.length; i++) {
    if (/^\s*(```|~~~)/.test(lines[i])) { prot[i] = true; fence = !fence; continue; }
    if (fence || /^\s*\|/.test(lines[i])) prot[i] = true;
  }
  const steps = lines.map((l, i) => !prot[i] && STEP.test(l) && !isImgLine(l) ? i : -1).filter(i => i >= 0);
  if (steps.length < 2) return pass(original);
  // end of the steps region: the first heading, or unindented non-list paragraph, after the last step
  let end = lines.length;
  for (let i = steps[steps.length - 1] + 1; i < lines.length; i++) {
    const l = lines[i];
    if (!l.trim() || isImgLine(l) || /^\s+\S/.test(l) || /^\s*[-*]\s/.test(l)) continue;
    end = i; break;
  }
  const blockOf = (i) => { let k = -1; for (let j = 0; j < steps.length; j++) if (steps[j] < i) k = j; return k; };
  // a target line must keep the image inside the list: a list item, or an indented continuation line
  const targetOk = (i) => !prot[i] && (/^\s*(?:\d+[.)]|[-*+])\s/.test(lines[i]) || /^\s+\S/.test(lines[i]));
  const blockLines = (k) => { const a = steps[k], b = k + 1 < steps.length ? steps[k + 1] : end;
    const r = []; for (let i = a; i < b; i++) if (lines[i].trim() && !isImgLine(lines[i]) && targetOk(i)) r.push(i); return r; };
  const blocks = steps.map((_, k) => { const ls = blockLines(k); return { ls, w: words(ls.map(i => lines[i]).join('\n')) }; });
  // trailing images (after the steps, e.g. above the Source line) move too, but only on a clearer match
  let tail = lines.length;
  for (let i = end; i < lines.length; i++) if (/^\s*(?:#{1,4}\s|\(?\*{0,2}_?\(?source)/i.test(lines[i])) { tail = i; break; }
  const moves = [];   // [from line, to line]
  for (let i = steps[0] + 1; i < tail; i++) {
    if (!isImgLine(lines[i]) || prot[i]) continue;
    const trailing = i >= end;
    const url = lines[i].match(IMG1)[1];
    const c = contextOf(url);
    if (!c || !c.wide.size) continue;
    const ctx = c.wide;
    const scores = blocks.map(b => 2 * overlap(c.near, b.w) + overlap(ctx, b.w));   // the sentence before the image counts double
    const best = scores.indexOf(Math.max(...scores));
    const here = blockOf(i);
    // inertia: an image already under a step that matches nearly as well stays put
    if (scores[best] < (trailing ? 2.0 : 1.2) || (!trailing && (best === here || (here >= 0 && scores[here] >= 0.75 * scores[best])))) continue;
    // within the step: the line that best matches the sentence right before the image (wider text breaks ties)
    const lineScore = (j) => { const lw = words(lines[j]); return overlap(c.last, lw) * 10 + overlap(c.near, lw) * 3 + overlap(ctx, lw); };
    let target = blocks[best].ls.reduce((m, j) => lineScore(j) > lineScore(m) ? j : m, blocks[best].ls[0]);
    const indentFrom = target;
    // never split a paragraph: go to its last line (lazy continuation lines belong to the same list item)
    while (target + 1 < lines.length && lines[target + 1].trim() && !prot[target + 1] && !isImgLine(lines[target + 1])
           && !/^\s*(?:\d+[.)]|[-*+])\s/.test(lines[target + 1])) target++;
    moves.push([i, target, indentFrom]);
  }
  if (!moves.length) return pass(original);
  const moving = new Set(moves.map(m => m[0]));
  const after = new Map();
  for (const [from, to, indentFrom] of moves) {
    const t = lines[indentFrom];
    const indent = (t.match(/^(\s*)(?:\d+[.)]|[-*])\s+/) ?? [null, t.match(/^\s*/)[0]]);
    const pad = indent[0] ? ' '.repeat(indent[0].length) : indent[1];
    (after.get(to) ?? after.set(to, []).get(to)).push(pad + lines[from].trim());
  }
  const outLines = [];
  for (let i = 0; i < lines.length; i++) {
    if (moving.has(i)) {                     // drop the image and one blank line left behind
      if (outLines.length && !outLines[outLines.length - 1].trim() && (i + 1 >= lines.length || !lines[i + 1].trim())) outLines.pop();
      continue;
    }
    outLines.push(lines[i]);
    if (after.has(i)) for (const img of after.get(i)) outLines.push('', img);
    if (after.has(i) && i + 1 < lines.length && lines[i + 1].trim()) outLines.push('');
  }
  const fixed = outLines.join('\n').replace(/\n{3,}/g, '\n\n');
  const count = (t) => (t.match(IMG) ?? []).length;
  return pass(count(fixed) === count(original) ? fixed : original);
} catch (e) {
  return pass(original);
}
